def dedent_lines(text, n):
    def strip_line(line):
        leading = len(line) - len(line.lstrip(' '))
        cut = min(leading, n)
        return line[cut:]
    return '\n'.join(strip_line(l) for l in text.split('\n'))

def count_set_bits(n):
    def helper(x):
        if x == 0:
            return 0
        return (x & 1) + helper(x >> 1)
    return helper(abs(n))

