from itertools import groupby

def longest_non_decreasing_run_length(lst):
    if not lst:
        return 0
    flags = [lst[i] >= lst[i - 1] for i in range(1, len(lst))]
    best = 1
    for key, group in groupby(flags):
        if key:
            best = max(best, len(list(group)) + 1)
    return best

